function encode(command) {
  var obj;
  if (Array.isArray(command)) {
    if (command.length !== 2) {
      throw new Error("xy command must have exactly 2 channels");
    }
    for (var i = 0; i < 2; i++) {
      var v = command[i];
      if (typeof v !== "number" || !isFinite(v) || Math.abs(v) > 0.1) {
        throw new Error("channel value out of range [-0.1, 0.1]");
      }
    }
    obj = { op: "step", channels: [command[0], command[1]] };
  } else if (command && typeof command === "object") {
    if (command.op === "lift") {
      if (command.position !== "up" && command.position !== "down") {
        throw new Error("lift position must be up or down");
      }
      obj = { op: "lift", position: command.position };
    } else if (command.op === "grip") {
      if (command.state !== "open" && command.state !== "closed") {
        throw new Error("grip state must be open or closed");
      }
      obj = { op: "grip", state: command.state };
    } else {
      throw new Error("unknown command op");
    }
  } else {
    throw new Error("unsupported command type");
  }
  return JSON.stringify(obj) + "\n";
}

function decode(rawReply) {
  if (typeof rawReply !== "string") {
    throw new Error("reply must be a string");
  }
  var text = rawReply.trim();
  if (text.length === 0) {
    throw new Error("empty reply");
  }
  if (text.indexOf("\n") !== -1 || text.indexOf("}{") !== -1) {
    throw new Error("reply must be exactly one JSON line");
  }
  var reply = JSON.parse(text);
  if (reply === null || typeof reply !== "object" || Array.isArray(reply)) {
    throw new Error("reply is not a JSON object");
  }
  if (reply.ok !== true) {
    throw new Error("device rejected command: " + (reply.error || "ok false"));
  }
  if (reply.limited !== undefined && typeof reply.limited !== "boolean") {
    throw new Error("limited field must be boolean");
  }
  var acc = reply.accepted;
  if (Array.isArray(acc)) {
    if (acc.length !== 2 || typeof acc[0] !== "number" || typeof acc[1] !== "number" ||
        !isFinite(acc[0]) || !isFinite(acc[1]) ||
        Math.abs(acc[0]) > 0.1 || Math.abs(acc[1]) > 0.1) {
      throw new Error("invalid accepted step array");
    }
  } else if (acc === null || typeof acc !== "object") {
    throw new Error("accepted field missing or invalid");
  } else if (acc.op === "lift") {
    if (acc.position !== "up" && acc.position !== "down") {
      throw new Error("invalid accepted lift");
    }
  } else if (acc.op === "grip") {
    if (acc.state !== "open" && acc.state !== "closed") {
      throw new Error("invalid accepted grip");
    }
  } else {
    throw new Error("unknown accepted object");
  }
  return { applied: acc, limited: reply.limited === true };
}

