function control(state) {
  if (!state || !Array.isArray(state.tip) || !Array.isArray(state.target)) {
    return { action: "stop", reason: "bad state" };
  }
  var ex = state.target[0] - state.tip[0];
  var ey = state.target[1] - state.tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) {
    return { action: "stop", reason: "non-finite error" };
  }
  var tol = (typeof state.tolerancePx === "number") ? state.tolerancePx : 7;
  if (err <= tol) {
    return { action: "verify" };
  }
  if (typeof state.maxActions === "number" && typeof state.step === "number" && state.step >= state.maxActions) {
    return { action: "stop", reason: "action budget reached" };
  }

  var h = Array.isArray(state.history) ? state.history : [];
  var start = Math.max(0, h.length - 12);
  var A = [[0, 0], [0, 0]];
  var C = [[0, 0], [0, 0]];
  var n = 0;
  for (var k = start; k < h.length; k++) {
    var s = h[k];
    if (!s || !Array.isArray(s.applied) || !Array.isArray(s.delta)) continue;
    var a = s.applied, d = s.delta;
    if (a.length !== 2 || d.length !== 2) continue;
    var vals = [a[0], a[1], d[0], d[1]];
    var okv = true;
    for (var q = 0; q < 4; q++) {
      if (typeof vals[q] !== "number" || !isFinite(vals[q])) { okv = false; }
    }
    if (!okv) continue;
    n++;
    for (var i = 0; i < 2; i++) {
      for (var j = 0; j < 2; j++) {
        A[i][j] += a[j] * a[i];
        C[i][j] += d[i] * a[j];
      }
    }
  }

  var probeFallback = (h.length % 2 === 0) ? [0.05, 0] : [0, 0.05];
  var detA = A[0][0] * A[1][1] - A[0][1] * A[1][0];
  var scaleA = Math.abs(A[0][0]) + Math.abs(A[1][1]);
  if (n < 2 || !isFinite(detA) || Math.abs(detA) <= 1e-9 * (scaleA * scaleA + 1e-12)) {
    return { action: "move", u: probeFallback };
  }

  var invA = [[A[1][1] / detA, -A[0][1] / detA], [-A[1][0] / detA, A[0][0] / detA]];
  // J maps applied channel inputs to pixel displacement: delta = J * applied
  var J = [[0, 0], [0, 0]];
  for (var r = 0; r < 2; r++) {
    for (var c = 0; c < 2; c++) {
      J[r][c] = C[r][0] * invA[0][c] + C[r][1] * invA[1][c];
    }
  }
  if (!isFinite(J[0][0]) || !isFinite(J[0][1]) || !isFinite(J[1][0]) || !isFinite(J[1][1])) {
    return { action: "move", u: probeFallback };
  }

  // Damped least squares: u = (JtJ + lam I)^-1 Jt e
  var M00 = J[0][0] * J[0][0] + J[1][0] * J[1][0];
  var M01 = J[0][0] * J[0][1] + J[1][0] * J[1][1];
  var M11 = J[0][1] * J[0][1] + J[1][1] * J[1][1];
  var lam = 1e-3 * (M00 + M11) + 1e-12;
  M00 += lam;
  M11 += lam;
  var detM = M00 * M11 - M01 * M01;
  if (!isFinite(detM) || Math.abs(detM) < 1e-15) {
    return { action: "move", u: probeFallback };
  }
  var g0 = J[0][0] * ex + J[1][0] * ey;
  var g1 = J[0][1] * ex + J[1][1] * ey;
  var u0 = (M11 * g0 - M01 * g1) / detM;
  var u1 = (-M01 * g0 + M00 * g1) / detM;
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: "move", u: probeFallback };
  }

