    u0 = u0 * 0.1 / norm;
    u1 = u1 * 0.1 / norm;
  }
  if (norm < 1e-4) {
    return { action: "move", u: probeFallback };
  }
  if (Math.abs(u0) > 0.1) u0 = u0 > 0 ? 0.1 : -0.1;
  if (Math.abs(u1) > 0.1) u1 = u1 > 0 ? 0.1 : -0.1;
  return { action: "move", u: [u0, u1] };
}
